#ifndef SN_SDK_BUILD_ID
#error "Pinned native SDK build identity is required"
#endif
#ifndef SN_EVALUATION_CAP
#define SN_EVALUATION_CAP 192
#endif
static_assert(SN_EVALUATION_CAP >= 192 && SN_EVALUATION_CAP <= 200000);
namespace {
using irred::statistics::DensityStatus; using irred::statistics::MatrixKind;
constexpr std::size_t N=1590, max_evaluations=SN_EVALUATION_CAP;
constexpr double forward_budget=1e-8;
const std::string table_sha="1cb0fc379ef066afdc2ffd1857681cc478024570d8a3eba284fb645775198cf8";
const std::string covariance_sha="5edd58efb7a29825a29246a29c90e3d95ddcabe9cf7cdb063b271824f221c66e";
void need(bool value,const char* reason){if(!value)throw std::runtime_error(reason);}
std::string hash(const std::vector<unsigned char>& b){std::array<unsigned char,SHA256_DIGEST_LENGTH> h{};need(SHA256(b.data(),b.size(),h.data())!=nullptr,"digest failure");std::ostringstream s;s<<std::hex<<std::setfill('0');for(auto x:h)s<<std::setw(2)<<unsigned(x);return s.str();}
std::vector<unsigned char> file(const char* name,std::size_t cap){std::ifstream f(name,std::ios::binary);need(bool(f),"missing admitted input");std::vector<unsigned char>b;char c;while(f.get(c)){need(b.size()<cap,"file bound");b.push_back(static_cast<unsigned char>(c));}need(f.eof(),"input read failure");return b;}
std::uint64_t uint64(const unsigned char* p){std::uint64_t v=0;for(std::size_t i=0;i<8;++i)v=(v<<8)|p[i];return v;}
double number(const unsigned char* p){double x=std::bit_cast<double>(uint64(p));need(std::isfinite(x),"nonfinite source or residual");return x;}
irred::statistics::Metadata metadata(const std::vector<std::string>& ids){irred::statistics::Metadata m;m.ordered_ids=ids;m.measure="dm_b_corr in mag";m.table_identity=table_sha;m.uncertainty_identity=covariance_sha;m.ordering_provenance="source2a7b21c zHD>0.01 original occurrence order;1590 including10calflags";m.calibration_provenance="released conditioned m_b_corr and STAT+SYS once; relative factor uses no CEPH_DIST mean";m.dependence_provenance="full selected principal covariance; no cross-probe independence claim";m.source_semantics="relative Pantheon+ original selected symmetric covariance; direct CLASS source-frame mean; normalized Gaussian";m.input_matrix_convention="covariance";m.matrix_validation_scope=irred::statistics::MatrixValidationScope::selected_covariance_only;return m;}
irred::statistics::Gaussian prepare(const std::vector<double>& c,const std::vector<std::string>& ids){auto m=metadata(ids);auto bound=irred::statistics::gaussian_preparation_payload_bound(ids.size(),MatrixKind::covariance,irred::numerics::Arithmetic::binary64_legacy_v1,m);need(bound && *bound<=256*1024*1024,"native preparation payload bound");auto g=irred::statistics::prepare_gaussian(c,MatrixKind::covariance,std::move(m),c.size(),forward_budget,irred::numerics::Arithmetic::binary64_legacy_v1);need(g.status()==DensityStatus::finite && g.numerical_status()==irred::numerics::Status::ok,"native Gaussian preparation refused");return g;}
void controls(){std::vector<std::string>ids={"analytic:0","analytic:1","analytic:2"};std::vector<double>c={2,0,0,0,3,0,0,0,4};auto g=prepare(c,ids);std::vector<double>r={.5,1,2};auto v=g.evaluate(r,ids,forward_budget);const double truth=-.5*(.25/2+1./3+4./4+std::log(24.)+3*std::log(2*std::acos(-1.)));need(v.density.status==DensityStatus::finite && std::abs(v.density.log_value-truth)<=1e-12,"analytic normalization control");auto wrong=ids;std::swap(wrong[0],wrong[1]);need(g.evaluate(r,wrong,forward_budget).density.status==DensityStatus::incompatible_metadata,"order refusal control");r[0]=std::numeric_limits<double>::quiet_NaN();need(g.evaluate(r,ids,forward_budget).density.status!=DensityStatus::finite,"nonfinite residual control");auto bad=c;bad[1]=.25;auto b=irred::statistics::prepare_gaussian(bad,MatrixKind::covariance,metadata(ids),9,forward_budget);need(b.status()!=DensityStatus::finite,"nonsymmetric covariance control");std::cout<<"{\"status\":\"controls_passed\",\"normalized_loglike\":"<<v.density.log_value<<",\"analytic_truth\":"<<truth<<",\"ordering_refused\":true,\"nonfinite_refused\":true,\"nonsymmetric_refused\":true}\n";}
}
int main(int argc,char**argv){std::cout<<std::setprecision(17);try{need(std::numeric_limits<double>::digits==53 && std::fegetround()==FE_TONEAREST,"binary64 round mode");if(argc==2 && std::string(argv[1])=="--controls"){controls();return 0;}need(argc==4,"closed native arguments");auto bytes=file(argv[1],N*N*8);need(bytes.size()==N*N*8 && hash(bytes)==covariance_sha,"exact selected covariance identity");std::vector<double>cov(N*N);for(std::size_t i=0;i<cov.size();++i)cov[i]=number(bytes.data()+8*i);auto axis_bytes=file(argv[2],16384);need(hash(axis_bytes)==argv[3],"exact occurrence axis identity");std::string axis(axis_bytes.begin(),axis_bytes.end());std::istringstream a(axis);std::vector<std::string>ids;std::size_t index,previous=0;while(a>>index){need(index<1701 && (ids.empty() || index>previous),"source occurrence order");ids.push_back(table_sha+":row:"+std::to_string(index));previous=index;}need(a.eof() && ids.size()==N,"exact1590 axis");auto g=prepare(cov,ids);std::vector<double>ones(N,1.0);std::cout<<"{\"status\":\"ready\",\"rows\":1590,\"sdk_build_id\":\""<<SN_SDK_BUILD_ID<<"\",\"covariance_sha256\":\""<<covariance_sha<<"\"}\n"<<std::flush;std::size_t count=0;std::vector<unsigned char>wire(N*8);while(true){std::array<unsigned char,16>head{};std::cin.read(reinterpret_cast<char*>(head.data()),head.size());need(bool(std::cin),"truncated frame header");const auto seq=uint64(head.data()),n=uint64(head.data()+8);if(seq==std::numeric_limits<std::uint64_t>::max()){need(n==0 && std::cin.peek()==EOF,"closed end marker");break;}need(seq==count && n==N && count<max_evaluations,"ordered bounded frame");std::cin.read(reinterpret_cast<char*>(wire.data()),wire.size());need(bool(std::cin),"truncated residual frame");std::vector<double>r(N);for(std::size_t i=0;i<N;++i)r[i]=number(wire.data()+8*i);const auto result=g.evaluate(r,ids,forward_budget);need(result.density.status==DensityStatus::finite && result.density.numerical_status==irred::numerics::Status::ok,"native Gaussian evaluation refused");need(std::isfinite(result.density.log_value)&&std::isfinite(result.quadratic)&&result.estimated_forward_sensitivity<=forward_budget,"native Gaussian diagnostic budget");const auto profile=g.profile_offset(r,ones,ids,forward_budget);need(profile.status==DensityStatus::finite && profile.numerical_status==irred::numerics::Status::ok && std::isfinite(profile.coefficient) && std::isfinite(profile.quadratic) && profile.estimated_forward_sensitivity<=forward_budget && profile.coefficient_solve_forward_sensitivity<=forward_budget,"native profile diagnostic refusal");std::cout<<"{\"status\":\"finite\",\"sequence\":"<<count<<",\"residual_sha256\":\""<<hash(wire)<<"\",\"loglike\":"<<result.density.log_value<<",\"quadratic\":"<<result.quadratic<<",\"logdet\":"<<result.log_determinant<<",\"normalization\":"<<result.normalization<<",\"backward_residual\":"<<result.backward_residual<<",\"forward_sensitivity\":"<<result.estimated_forward_sensitivity<<",\"profile_delta_M\":"<<profile.coefficient<<",\"profile_quadratic\":"<<profile.quadratic<<",\"profile_forward_sensitivity\":"<<profile.estimated_forward_sensitivity<<",\"profile_coefficient_forward_sensitivity\":"<<profile.coefficient_solve_forward_sensitivity<<"}\n"<<std::flush;++count;}std::cout<<"{\"status\":\"closed\",\"evaluations\":"<<count<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';std::cout<<"{\"status\":\"refused\"}\n";return 1;}}
